import { useEffect, useRef, useState } from 'react';
import { Menu as MenuIcon, X } from 'lucide-react';
import Attorneys from './components/Attorneys';
import Testimonials from './components/Testimonials';
import Faq from './components/Faq';

// Domain design tokens (resolved server-side by the design system).
const tw = {"page_bg": "bg-slate-50", "surface": "bg-white", "surface_2": "bg-slate-100", "heading_text": "text-slate-900", "body_text": "text-slate-600", "muted_text": "text-slate-500", "primary": "bg-blue-900", "primary_hover": "hover:bg-blue-950", "on_primary": "text-white", "border": "border-slate-200", "accent_text": "text-blue-900", "accent_bg": "bg-blue-50", "gradient": "from-blue-900 to-slate-800"};
const RADIUS = "rounded-xl";
const GRAD = "bg-gradient-to-br from-blue-900 to-slate-800";
const FONT_CSS = ".font-display{font-family: 'Libre Baskerville', Georgia, serif;} .font-body{font-family: 'Source Sans 3', system-ui, sans-serif;} body{font-family: 'Source Sans 3', system-ui, sans-serif;}";
const LOGO_URL = "";

// Scroll-reveal wrapper: sections animate in as they enter the viewport
// (IntersectionObserver; no-ops during server render).
function Reveal({ children, delay = 0 }) {
  const ref = useRef(null);
  const [visible, setVisible] = useState(false);
  useEffect(() => {
    const el = ref.current;
    if (!el) return undefined;
    const io = new IntersectionObserver((entries) => {
      if (entries[0].isIntersecting) { setVisible(true); io.disconnect(); }
    }, { threshold: 0.12 });
    io.observe(el);
    // Fallback: embedded/short viewports may never fire the observer
    // (live: preview iframes without scroll) -- never leave content invisible.
    const t = setTimeout(() => { setVisible(true); io.disconnect(); }, 1200);
    return () => { clearTimeout(t); io.disconnect(); };
  }, []);
  return (
    <div
      ref={ref}
      style={{ animationDelay: delay ? `${delay}ms` : undefined }}
      className={`reveal ${visible ? 'reveal-visible' : ''}`}
    >{children}</div>
  );
}

export default function App() {
  const [menuOpen, setMenuOpen] = useState(false);
  const links = [
    { label: "Our Attorneys", href: "#attorneys" },
    { label: "Client Outcomes", href: "#testimonials" },
    { label: "FAQ", href: "#faq" },
  ];
  return (
    <div className={`min-h-screen ${tw.page_bg} ${tw.heading_text} font-body`}>
      <style>{FONT_CSS}</style>
      <header className={`sticky top-0 z-50 backdrop-blur-xl border-b ${tw.page_bg} ${tw.border}`}>
        <div className="max-w-6xl mx-auto px-6 h-16 flex items-center justify-between">
          <a href="#top" className="flex items-center gap-2">
            {LOGO_URL ? (
              <img src={LOGO_URL} alt="RautLaw" className="h-9 w-auto" />
            ) : (
              <span className={`w-9 h-9 ${GRAD} flex items-center justify-center ${tw.on_primary} font-black text-sm tracking-tight ${RADIUS}`}>R</span>
            )}
            <span className="font-display font-extrabold text-lg tracking-tight">RautLaw</span>
          </a>
          <nav className={`hidden md:flex items-center gap-8 text-sm font-medium ${tw.body_text}`}>
            {links.map(l => <a key={l.href} href={l.href} className="hover:opacity-70 transition-opacity">{l.label}</a>)}
          </nav>
          <div className="hidden md:flex items-center gap-3">
            <a href="#top" className={`px-4 py-2 ${tw.primary} ${tw.primary_hover} ${tw.on_primary} text-sm font-semibold ${RADIUS} transition-colors`}>Get started</a>
          </div>
          <button className="md:hidden p-2" onClick={() => setMenuOpen(!menuOpen)} aria-label="Menu">
            {menuOpen ? <X className="w-5 h-5" /> : <MenuIcon className="w-5 h-5" />}
          </button>
        </div>
        {menuOpen && (
          <div className={`md:hidden border-t px-6 py-4 space-y-3 ${tw.surface} ${tw.border}`}>
            {links.map(l => <a key={l.href} href={l.href} onClick={() => setMenuOpen(false)} className={`block font-medium ${tw.body_text}`}>{l.label}</a>)}
            <a href="#top" className={`block text-center px-4 py-2.5 ${tw.primary} ${tw.on_primary} font-semibold ${RADIUS}`}>Get started</a>
          </div>
        )}
      </header>
      <main id="top">
      <Reveal delay={0}><Attorneys /></Reveal>
      <Reveal delay={110}><Testimonials /></Reveal>
      <Reveal delay={220}><Faq /></Reveal>
      </main>
      <footer className={`border-t py-10 text-center text-sm ${tw.border} ${tw.muted_text}`}>
        <div className="flex items-center justify-center gap-2 mb-2">
          {LOGO_URL ? (
            <img src={LOGO_URL} alt="RautLaw" className="h-7 w-auto" />
          ) : (
            <span className={`w-7 h-7 ${GRAD} flex items-center justify-center ${tw.on_primary} font-black text-[11px] ${RADIUS}`}>R</span>
          )}
          <span className="font-display font-bold">RautLaw</span>
        </div>
        &copy; 2026 RautLaw. All rights reserved.
      </footer>
    </div>    );
}

