import React, { useState } from "react";

const Faq = () => {
  const [activeFaq, setActiveFaq] = useState(null);

  const faqs = [
    {
      question: "What is your return policy?",
      answer: "Our return policy is simple: if you're not 100% satisfied with your purchase, we'll give you a full refund within 30 days of receiving your item. If you're not fully satisfied, just let us know and we'll do our best to help you.",
    },
    // Add more FAQs as needed
  ];

  return (
    <section className="bg-slate-50 pt-20 pb-12 px-6 max-w-6xl mx-auto">
      <h2 className="text-slate-900 font-display text-4xl mb-8">FAQ</h2>
      <div className="flex flex-col gap-8">
        {faqs.map((faq, index) => (
          <div
            key={index}
            className={`border-slate-200 border-l-4 p-6 rounded-xl ${
              activeFaq === index ? "bg-white" : "bg-slate-50"
            }`}
          >
            <button
              className="flex justify-between items-start w-full"
              onClick={() =>
                activeFaq === index ? setActiveFaq(null) : setActiveFaq(index)
              }
            >
              <h3 className="font-display text-slate-900 font-medium text-lg">
                {faq.question}
              </h3>
              <span
                className={`transition-transform duration-300 ${
                  activeFaq === index ? "rotate-180" : ""
                }`}
              >
                ➔
              </span>
            </button>
            <p
              className={`mt-4 text-slate-600 ${
                activeFaq !== index ? "hidden" : ""
              }`}
            >
              {faq.answer}
            </p>
          </div>
        ))}
      </div>
    </section>
  );
};

export default Faq;

